const listUserProviders = `-- name: ListUserProviders :many
SELECT provider FROM identities WHERE user_id = $1 ORDER BY provider
`

func (q *Queries) ListUserProviders(ctx context.Context, userID int64) ([]string, error) {
	rows, err := q.db.Query(ctx, listUserProviders, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var provider string
		if err := rows.Scan(&provider); err != nil {
			return nil, err
		}
		items = append(items, provider)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

